package com.swarainstitute.app;

import org.json.*;
import java.time.LocalDate;
import java.time.LocalTime;
import java.util.*;

final class Database {
    static final String[] KEYS={"students","trainers","artists","courses","sessions","fees","registrations","events"};
    static JSONObject empty()throws Exception{JSONObject s=new JSONObject().put("version",1).put("institute","Swara Institute").put("audit",new JSONArray());for(String k:KEYS)s.put(k,new JSONArray());return s;}
    static JSONObject upgrade(JSONObject db)throws Exception{for(String k:KEYS)if(!db.has(k)||db.isNull(k))db.put(k,new JSONArray());if(!db.has("audit")||db.isNull("audit"))db.put("audit",new JSONArray());return db;}
    static JSONObject copy(JSONObject o)throws JSONException{return new JSONObject(o.toString());}
    static JSONObject find(JSONObject db,String key,String id)throws JSONException{JSONArray a=db.getJSONArray(key);for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(o.optString("id").equals(id))return o;}return null;}
    static boolean has(JSONArray a,String value){if(a==null)return false;for(int i=0;i<a.length();i++)if(value.equals(a.optString(i)))return true;return false;}
    static Set<String> ids(JSONArray a)throws JSONException{Set<String> set=new HashSet<>();for(int i=0;i<a.length();i++)set.add(a.getJSONObject(i).getString("id"));return set;}
    static boolean visible(JSONObject db,String k,JSONObject r,String role,String entity)throws JSONException{
        if(Arrays.asList("Owner","Admin","Finance").contains(role))return true;
        JSONObject student=role.equals("Student / Parent")?find(db,"students",entity):null;
        if(role.equals("Trainer")){if(k.equals("students"))return r.optString("trainerId").equals(entity);if(k.equals("trainers"))return r.optString("id").equals(entity);if(k.equals("sessions"))return r.optString("trainerId").equals(entity);if(k.equals("courses")){JSONArray studs=db.getJSONArray("students");for(int i=0;i<studs.length();i++)if(studs.getJSONObject(i).optString("trainerId").equals(entity)&&has(studs.getJSONObject(i).optJSONArray("courseIds"),r.optString("id")))return true;return false;}if(k.equals("events"))return has(r.optJSONArray("trainerIds"),entity);return false;}
        if(role.equals("Artist")){if(k.equals("artists"))return r.optString("id").equals(entity);if(k.equals("events"))return has(r.optJSONArray("artistIds"),entity);return false;}
        if(role.equals("Student / Parent")){if(k.equals("students"))return r.optString("id").equals(entity);if(k.equals("fees")||k.equals("sessions")||k.equals("registrations"))return r.optString("studentId").equals(entity);if(k.equals("courses"))return student!=null&&has(student.optJSONArray("courseIds"),r.optString("id"));if(k.equals("trainers"))return student!=null&&student.optString("trainerId").equals(r.optString("id"));if(k.equals("events"))return has(r.optJSONArray("studentIds"),entity);return false;}return false;
    }
    static JSONObject view(JSONObject db,String role,String entity)throws Exception{
        upgrade(db);JSONObject out=empty().put("institute",db.optString("institute")).put("demoData",db.optBoolean("demoData",false));
        for(String k:KEYS){JSONArray a=db.getJSONArray(k),dest=new JSONArray();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(!visible(db,k,r,role,entity))continue;JSONObject c=copy(r);
            if(!Arrays.asList("Owner","Admin","Finance").contains(role)){
                if(k.equals("events")){if(role.equals("Artist")){JSONArray payouts=new JSONArray(),costs=r.optJSONArray("expenses");if(costs!=null)for(int x=0;x<costs.length();x++){JSONObject cost=costs.getJSONObject(x);if(cost.optString("category").equals("Artist payout")&&cost.optString("artistId").equals(entity))payouts.put(copy(cost));}c.put("ownPayouts",payouts);}for(String x:new String[]{"collections","organizerCharge","organizerReceived","expenses","artistIds","studentIds","trainerIds","organizerMobile"})c.remove(x);}
                if(k.equals("trainers")){c.remove("age");c.remove("location");c.remove("profession");if(!role.equals("Trainer")){c.remove("commission");c.remove("email");c.remove("mobile");}else{JSONArray commissions=new JSONArray(),fs=db.getJSONArray("fees");for(int x=0;x<fs.length();x++){JSONObject fee=fs.getJSONObject(x),student=find(db,"students",fee.optString("studentId"));if(student!=null&&student.optString("trainerId").equals(entity)){JSONArray payments=fee.optJSONArray("payments");if(payments!=null)for(int p=0;p<payments.length();p++){JSONObject payment=payments.getJSONObject(p);commissions.put(new JSONObject().put("date",payment.optString("date")).put("commission",payment.optDouble("amount",0)*r.optDouble("commission",0)/100));}}}c.put("commissionReceipts",commissions);}}
                if(k.equals("students")&&role.equals("Trainer")){for(String x:new String[]{"feePlan","guardianMobile","email","location","profession"})c.remove(x);}
            }dest.put(c);}out.put(k,dest);}
        if(role.equals("Owner"))out.put("audit",db.optJSONArray("audit"));return out;
    }
    static boolean editable(String k,String role){return role.equals("Owner")||role.equals("Admin")||(role.equals("Finance")&&(k.equals("fees")||k.equals("registrations")||k.equals("events")))||(role.equals("Trainer")&&k.equals("sessions"))||(role.equals("Artist")&&k.equals("artists"));}
    static boolean equal(Object a,Object b)throws JSONException{
        if(a==b)return true;if(a==null||b==null)return false;
        if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(x.length()!=y.length())return false;Iterator<String> it=x.keys();while(it.hasNext()){String k=it.next();if(!y.has(k)||!equal(x.get(k),y.get(k)))return false;}return true;}
        if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int i=0;i<x.length();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}
        if(a instanceof Number&&b instanceof Number)return Double.compare(((Number)a).doubleValue(),((Number)b).doubleValue())==0;return a.equals(b);
    }
    static JSONObject merge(JSONObject old,JSONObject submitted,String role,String entity)throws Exception{
        upgrade(old);upgrade(submitted);JSONObject result=copy(old),visible=view(old,role,entity);String institution=submitted.optString("institute",old.getString("institute"));if(!institution.equals(old.getString("institute"))&&!role.equals("Owner"))throw new IllegalArgumentException("Only the owner can rename the institute.");result.put("institute",institution);
        for(String k:KEYS){JSONArray incoming=submitted.getJSONArray(k),shown=visible.getJSONArray(k),existing=old.getJSONArray(k);if(incoming.length()>10000)throw new IllegalArgumentException("Too many records.");
            if(!editable(k,role)){if(!equal(incoming,shown))throw new IllegalArgumentException("Your account cannot change "+k+".");continue;}
            Set<String> seen=new HashSet<>();JSONArray merged=new JSONArray();
            for(int i=0;i<incoming.length();i++){JSONObject n=incoming.getJSONObject(i);String id=n.getString("id");if(!seen.add(id))throw new IllegalArgumentException("Duplicate record ID.");JSONObject orig=find(old,k,id);
                if(orig!=null&&!visible(old,k,orig,role,entity))throw new IllegalArgumentException("That record is outside your account.");
                if(role.equals("Artist")){if(orig==null||!id.equals(entity))throw new IllegalArgumentException("Artists can only edit their own profile.");JSONObject prior=find(visible,k,id);JSONObject changed=copy(prior);for(String field:new String[]{"availability","stagePreference","payoutExpectation","socialLinks"})if(n.has(field))changed.put(field,n.get(field));if(!equal(changed,n))throw new IllegalArgumentException("Artist edits are limited to availability, preference and social details.");JSONObject full=copy(orig);for(String field:new String[]{"availability","stagePreference","payoutExpectation","socialLinks"})if(n.has(field))full.put(field,n.get(field));n=full;}
                if(role.equals("Trainer")&&!n.optString("trainerId").equals(entity))throw new IllegalArgumentException("You can only manage your assigned sessions.");
                if(k.equals("sessions")&&(orig==null||!orig.optString("trainerId").equals(n.optString("trainerId"))||!orig.optString("studentId").equals(n.optString("studentId")))){JSONObject student=find(editable("students",role)?submitted:old,"students",n.optString("studentId"));if(student==null||!student.optString("trainerId").equals(n.optString("trainerId")))throw new IllegalArgumentException("Select the student's assigned trainer.");}
                if(k.equals("fees")&&orig!=null)immutableLedger(orig.optJSONArray("payments"),n.optJSONArray("payments"),"payment");
                if(k.equals("registrations")&&orig!=null&&!equal(orig,n))throw new IllegalArgumentException("Recorded registration payments cannot be altered.");
                if(k.equals("events")&&orig!=null)immutableLedger(orig.optJSONArray("expenses"),n.optJSONArray("expenses"),"expense");
                merged.put(n);
            }
            for(int i=0;i<existing.length();i++){JSONObject orig=existing.getJSONObject(i);String id=orig.getString("id");if(seen.contains(id))continue;if(!visible(old,k,orig,role,entity)){merged.put(orig);continue;}if(k.equals("fees")||k.equals("registrations")||k.equals("events")||!Arrays.asList("Owner","Admin").contains(role))throw new IllegalArgumentException("This record cannot be deleted. Change its status instead.");}
            result.put(k,merged);
        }
        validate(result);return result;
    }
    static void immutableLedger(JSONArray previous,JSONArray next,String label)throws Exception{
        if(previous==null)return;if(next==null||next.length()<previous.length())throw new IllegalArgumentException("Recorded "+label+" entries cannot be deleted.");
        for(int i=0;i<previous.length();i++)if(!equal(previous.getJSONObject(i),next.getJSONObject(i)))throw new IllegalArgumentException("Recorded "+label+" entries cannot be altered. Contact the owner to restore a corrected backup if needed.");
    }
    static void required(JSONObject r,String...fields)throws Exception{for(String f:fields)if(!r.has(f)||r.isNull(f)||r.optString(f).trim().isEmpty()||(r.opt(f)instanceof JSONArray&&r.getJSONArray(f).length()==0))throw new IllegalArgumentException(f+" is required.");}
    static double number(JSONObject r,String k,double fallback)throws Exception{if(!r.has(k))return fallback;double n=r.getDouble(k);if(!Double.isFinite(n)||n<0)throw new IllegalArgumentException(k+" must be a non-negative number.");return n;}
    static void ref(JSONObject db,JSONObject r,String field,String key)throws Exception{if(find(db,key,r.optString(field))==null)throw new IllegalArgumentException("Unknown "+field+". Create the profile first.");}
    static void refs(JSONObject db,JSONObject r,String field,String key)throws Exception{JSONArray a=r.optJSONArray(field);if(a==null)return;for(int i=0;i<a.length();i++)if(find(db,key,a.getString(i))==null)throw new IllegalArgumentException("Unknown linked "+key+" record.");}
    static void date(JSONObject r,String field)throws Exception{if(r.optString(field).isEmpty())return;try{LocalDate.parse(r.getString(field));}catch(Exception ex){throw new IllegalArgumentException("Invalid "+field+".");}}
    static void status(JSONObject r,String...values)throws Exception{if(!Arrays.asList(values).contains(r.optString("status")))throw new IllegalArgumentException("Unsupported record status.");}
    static void uniqueProfile(JSONObject db,String key,JSONObject r)throws Exception{String mobile=r.optString("mobile").replaceAll("\\D","");if(mobile.isEmpty())return;JSONArray rows=db.getJSONArray(key);for(int i=0;i<rows.length();i++){JSONObject other=rows.getJSONObject(i);if(other.optString("id").equals(r.optString("id")))continue;if(other.optString("name").trim().equalsIgnoreCase(r.optString("name").trim())&&other.optString("mobile").replaceAll("\\D","").equals(mobile))throw new IllegalArgumentException((key.equals("artists")?"An ":"A ")+(key.equals("students")?"student":key.equals("trainers")?"trainer":"artist")+" with this name and mobile number already exists.");}}
    static void uniqueNamed(JSONObject db,String key,JSONObject r)throws Exception{JSONArray rows=db.getJSONArray(key);for(int i=0;i<rows.length();i++){JSONObject other=rows.getJSONObject(i);if(other.optString("id").equals(r.optString("id")))continue;boolean sameName=other.optString("name").trim().equalsIgnoreCase(r.optString("name").trim());if(key.equals("courses")&&sameName)throw new IllegalArgumentException("A work packet with this name already exists.");if(key.equals("events")&&sameName&&other.optString("date").equals(r.optString("date")))throw new IllegalArgumentException("A concert with this name and date already exists.");}}
    static void validate(JSONObject db)throws Exception{
        upgrade(db);required(db,"institute");if(db.getString("institute").length()>80||db.optInt("version")!=1)throw new IllegalArgumentException("Unsupported institute data.");Set<String> all=new HashSet<>(),receipts=new HashSet<>();
        for(String k:KEYS){JSONArray a=db.getJSONArray(k);if(a.length()>10000)throw new IllegalArgumentException("Too many records.");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);required(r,"id");if(!all.add(r.getString("id")))throw new IllegalArgumentException("Duplicate record IDs.");if(r.toString().length()>100000)throw new IllegalArgumentException("Record is too large.");for(String n:new String[]{"age","commission","fee","sessions","amount","discount","duration","batchSize","collections","organizerCharge","organizerReceived","payoutExpectation","audience"})if(!(k.equals("courses")&&n.equals("duration")&&!r.has("durationUnit")))number(r,n,0);if(r.has("durationUnit")&&!Arrays.asList("Days","Months","Years").contains(r.optString("durationUnit")))throw new IllegalArgumentException("Duration unit must be Days, Months or Years.");if(r.has("age")&&(r.getDouble("age")<1||r.getDouble("age")>120))throw new IllegalArgumentException("Age must be between 1 and 120.");for(String m:new String[]{"mobile","guardianMobile"})if(r.has(m)&&!r.optString(m).isEmpty()&&!r.getString(m).matches("\\+?[0-9 ()-]{7,18}"))throw new IllegalArgumentException("Invalid "+(m.equals("guardianMobile")?"guardian mobile":"mobile")+" number.");if(!r.optString("email").isEmpty()&&!r.optString("email").matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw new IllegalArgumentException("Invalid email address.");for(String d:new String[]{"enrollmentDate","plannedDate","actualDate","dueDate","date","nextSessionDate"})date(r,d);if(!r.optString("time").isEmpty())try{LocalTime.parse(r.getString("time"));}catch(Exception ex){throw new IllegalArgumentException("Invalid class time.");}
            switch(k){case "students":if(r.optBoolean("importPending",false)){required(r,"name","status");if(!r.has("courseIds"))r.put("courseIds",new JSONArray());if(!r.has("trainerId"))r.put("trainerId","");status(r,"Enquiry","Active","Paused","Completed","Dropped","Alumni");}else{required(r,"name","age","mobile","location","courseIds","trainerId","status","enrollmentDate");ref(db,r,"trainerId","trainers");refs(db,r,"courseIds","courses");status(r,"Enquiry","Active","Paused","Completed","Dropped","Alumni");uniqueProfile(db,k,r);}break;
            case "trainers":required(r,"name","mobile","expertise","availability","commission","status");if(number(r,"commission",0)>100)throw new IllegalArgumentException("Commission cannot exceed 100%.");status(r,"Active","Inactive");uniqueProfile(db,k,r);break;
            case "artists":required(r,"name","mobile","expertise","category","availability","status");status(r,"Active","Inactive");uniqueProfile(db,k,r);break;
            case "courses":required(r,"name","category","subcategory","feeType","fee","sessions","status");double sessions=number(r,"sessions",0);if(sessions<1||sessions!=Math.floor(sessions))throw new IllegalArgumentException("Course sessions must be a positive whole number.");status(r,"Active","Inactive");uniqueNamed(db,k,r);break;
            case "sessions":required(r,"studentId","trainerId","courseId","plannedDate","status");ref(db,r,"studentId","students");ref(db,r,"trainerId","trainers");ref(db,r,"courseId","courses");JSONObject student=find(db,"students",r.getString("studentId"));if(!has(student.getJSONArray("courseIds"),r.getString("courseId")))throw new IllegalArgumentException("Session must use an enrolled course.");status(r,"Planned","Completed","Missed","Rescheduled","Cancelled");if(r.getString("status").equals("Completed")){required(r,"actualDate");if(!r.optString("attendance").equals("Present"))throw new IllegalArgumentException("Completed sessions require present attendance.");}if(r.getString("status").equals("Rescheduled"))required(r,"rescheduleReason");break;
            case "fees":required(r,"studentId","courseId","amount","dueDate");ref(db,r,"studentId","students");ref(db,r,"courseId","courses");JSONObject fs=find(db,"students",r.getString("studentId"));if(!has(fs.getJSONArray("courseIds"),r.getString("courseId")))throw new IllegalArgumentException("Fee must use an enrolled course.");double amount=number(r,"amount",0),discount=number(r,"discount",0),total=0;if(discount>amount)throw new IllegalArgumentException("Discount exceeds the fee.");JSONArray payments=r.getJSONArray("payments");Set<String> paymentIds=new HashSet<>();for(int p=0;p<payments.length();p++){JSONObject payment=payments.getJSONObject(p);required(payment,"id","amount","date","mode","receipt");date(payment,"date");if(!paymentIds.add(payment.getString("id"))||!receipts.add(payment.getString("receipt").toLowerCase(Locale.ROOT).trim()))throw new IllegalArgumentException("Duplicate receipt or payment ID.");double paid=number(payment,"amount",0);if(paid<=0)throw new IllegalArgumentException("Payment must be above zero.");total+=paid;}if(total>amount-discount+.001)throw new IllegalArgumentException("Payments exceed the fee balance.");break;
            case "registrations":required(r,"studentId","amount","date","mode","receipt","status");ref(db,r,"studentId","students");if(number(r,"amount",0)<=0)throw new IllegalArgumentException("Registration amount must be above zero.");status(r,"Paid");String registrationReceipt=r.getString("receipt").toLowerCase(Locale.ROOT).trim();if(!receipts.add(registrationReceipt))throw new IllegalArgumentException("Duplicate receipt number.");break;
            case "events":required(r,"name","date","duration","organizer","status");status(r,"Planned","Confirmed","Completed","Cancelled");refs(db,r,"artistIds","artists");refs(db,r,"studentIds","students");refs(db,r,"trainerIds","trainers");if(number(r,"organizerReceived",0)>number(r,"organizerCharge",0))throw new IllegalArgumentException("Organizer received exceeds the billed charge.");JSONArray expenses=r.getJSONArray("expenses");Set<String> expenseIds=new HashSet<>();for(int x=0;x<expenses.length();x++){JSONObject cost=expenses.getJSONObject(x);required(cost,"id","category","amount","date","description");date(cost,"date");if(!expenseIds.add(cost.getString("id")))throw new IllegalArgumentException("Duplicate expense ID.");if(number(cost,"amount",0)<=0)throw new IllegalArgumentException("Expense must be above zero.");if(cost.getString("category").equals("Artist payout")&&!has(r.optJSONArray("artistIds"),cost.optString("artistId")))throw new IllegalArgumentException("Payout must be linked to a participating artist.");}uniqueNamed(db,k,r);break;}
        }}
    }
    static void validateAccount(JSONObject db,String role,String entity)throws Exception{String k=role.equals("Trainer")?"trainers":role.equals("Artist")?"artists":role.equals("Student / Parent")?"students":"";if(!Arrays.asList("Admin","Trainer","Artist","Student / Parent","Finance").contains(role))throw new IllegalArgumentException("Unsupported account role.");if(!k.isEmpty()&&find(db,k,entity)==null)throw new IllegalArgumentException("Select a matching "+role+" profile.");if(k.isEmpty()&&!entity.isEmpty())throw new IllegalArgumentException("Admin and finance accounts do not need a linked profile.");}
    static void audit(JSONObject db,String user,String action)throws JSONException{JSONArray old=db.optJSONArray("audit"),out=new JSONArray();out.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("at",java.time.Instant.now().toString()).put("user",user).put("action",action.substring(0,Math.min(500,action.length()))));if(old!=null)for(int i=0;i<Math.min(499,old.length());i++)out.put(old.get(i));db.put("audit",out);}
}
